import json
import sys

def dump(path, md_lines=4):
    with open(path) as f:
        nb = json.load(f)
    print("=" * 30, path, "=" * 30)
    for i, cell in enumerate(nb["cells"]):
        src = "".join(cell["source"])
        tag = cell["cell_type"]
        print(f"--- cell {i} [{tag}] ---")
        if tag == "markdown":
            lines = src.split("\n")
            for l in lines[:md_lines]:
                print(l)
        else:
            for j, line in enumerate(src.split("\n"), 1):
                print(f"{j:4d} {line}")

if __name__ == "__main__":
    for p in sys.argv[1:]:
        dump(p)

